 if (select count(*) from public.participants_v2 where event_id='AIA-TECH-20261023-UAT' and not is_archived)<>0 then raise exception 'AIA random-registration fixture must start empty'; end if;
 if (select count(*) from public.teams_v2 where event_id='AIA-TECH-20261023-UAT' and is_active)<>25 then raise exception 'AIA certification team assertion failed'; end if;
 if coalesce((select event_payload #>> '{TeamFormation,Mode}' from public.events_v2 where event_id='AIA-TECH-20261023-UAT'),'')<>'RANDOM_ASSIGN' then raise exception 'AIA random registration assertion failed'; end if;
 if coalesce((select event_payload #>> '{Attendance,SchemaVersion}' from public.events_v2 where event_id='AIA-TECH-20261023-UAT'),'')<>'1' then raise exception 'AIA attendance configuration assertion failed'; end if;
end $assert$;
